export const categories = ['Canned goods', 'Dry goods', 'Produce', 'Toiletries'] as const;

export type Category = (typeof categories)[number];

export type PantryItem = {
  id: string;
  name: string;
  category: Category;
  quantity: number;
  /** Local calendar date, `YYYY-MM-DD`. */
  lastRestocked: string;
};

/** At or below this many on hand, an item shows as low stock. */
export const LOW_STOCK = 10;

export const sampleItems: PantryItem[] = [
  { id: 'chickpeas', name: 'Chickpeas', category: 'Canned goods', quantity: 24, lastRestocked: '2026-10-14' },
  { id: 'tomato-soup', name: 'Tomato soup', category: 'Canned goods', quantity: 8, lastRestocked: '2026-10-02' },
  { id: 'brown-rice', name: 'Brown rice', category: 'Dry goods', quantity: 15, lastRestocked: '2026-10-11' },
  { id: 'rolled-oats', name: 'Rolled oats', category: 'Dry goods', quantity: 6, lastRestocked: '2026-09-28' },
  { id: 'apples', name: 'Apples', category: 'Produce', quantity: 30, lastRestocked: '2026-10-15' },
  { id: 'potatoes', name: 'Potatoes', category: 'Produce', quantity: 12, lastRestocked: '2026-10-13' },
  { id: 'toothpaste', name: 'Toothpaste', category: 'Toiletries', quantity: 9, lastRestocked: '2026-10-05' },
  { id: 'shampoo', name: 'Shampoo', category: 'Toiletries', quantity: 4, lastRestocked: '2026-09-30' },
];

export function today(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });

export function formatDate(value: string): string {
  const [year, month, day] = value.split('-').map(Number);
  return dateFormat.format(new Date(year!, month! - 1, day!));
}
EOF
